mapper.insert:
INSERT INTO game_poet_quiz_answer(
    attempt_id,
    question_id,
    option_id
) VALUES (
             #{attemptId},
             #{questionId},
             #{optionId}
         )
    ON DUPLICATE KEY UPDATE
                         option_id = #{optionId}

mapper.select:
SELECT COUNT(1)
FROM game_poet_quiz_attempt a

    a.user_id = #{userId}

        AND a.status = #{status}

SELECT a.id AS attemptId, a.quiz_id AS quizId, q.title AS quizTitle, a.status AS status, a.total_questions AS totalQuestions, a.answered_count AS answeredCount, a.result_poet_id AS resultPoetId, a.result_score AS resultScore, a.started_at AS startedAt, a.finished_at AS finishedAt, p.name AS resultPoetName, p.dynasty AS resultPoetDynasty, p.avatar_url AS resultPoetAvatarUrl, p.persona_title AS resultPoetPersonaTitle FROM game_poet_quiz_attempt a LEFT JOIN game_poet_quiz q ON q.id = a.quiz_id LEFT JOIN game_poet_profile p ON p.id = a.result_poet_id
a.user_id = #{userId}
AND a.status = #{status}
ORDER BY a.created_at DESC, a.id DESC LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM game_poet_quiz_attempt
WHERE id = #{attemptId}
  AND user_id = #{userId}

mapper.select:
SELECT COUNT(1)
FROM game_poet_quiz_answer
WHERE attempt_id = #{attemptId} AND question_id = #{questionId}
